"""Render status using existing measured artifacts; never mark running experiments complete."""
import csv,json,shutil
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'docs/validation/aria_dt_20261012_02'
def load(p):return json.loads(p.read_text())
def main():
 old=OUT/'REPORT.md';archive=OUT/'REPORT_initial_preflight.md'
 if not archive.exists() and old.exists():shutil.copyfile(old,archive)
 p1=[]
 for cls in ('bottle','screw','carpet'):
  base=OUT/'p1_verified'/cls;banks={r['selector']:r for r in csv.DictReader((base/'bank_summary.csv').open())};lat=list(csv.DictReader((base/'latency_summary.csv').open()))
  for selector in ('coreset','ccifps','random_same_k'):
   metrics=load(base/selector/'pixel_metrics.json');gate=load(base/selector/'search_regression_faiss_gpu.json');r=next(r for r in lat if r['selector']==selector and r['backend']=='faiss_gpu');cpu=next(r for r in lat if r['selector']==selector and r['backend']=='numpy_chunk')
   p1.append(dict(class_name=cls,selector=selector,**{k:banks[selector][k] for k in ('K','bank_bytes','selection_s')},pixel_ap=metrics['ap'],pixel_auroc=metrics['auroc'],pixel_test_oracle_f1=metrics['f1_score'],image_threshold=float(r['threshold']),faiss_p50_ms=float(r['p50_ms']),faiss_p95_ms=float(r['p95_ms']),faiss_p99_ms=float(r['p99_ms']),numpy_p50_ms=float(cpu['p50_ms']),max_score_error=gate['max_absolute_score_error'],verdict_changes=gate['verdict_changes']))
 with (OUT/'p1_summary.csv').open('w') as f:w=csv.DictWriter(f,fieldnames=list(p1[0]));w.writeheader();w.writerows(p1)
 full=OUT/'des_full';n=sum(1 for _ in (full/'runs').glob('*/complete.json'));verify=full/'verification.json';gate=load(OUT/'des_pilot30/cost_gate.json');browser=OUT/'browser_v2/report.json';br=load(browser) if browser.exists() else {}
 status='P5 전 구성 완료·해시 검증 완료' if verify.exists() else f'P5 실행 중: 완료 마커 {n:,}/7,020 (최종 검증 전)'
 lines=['# ARIA DT 실행 보고서','',status+'. P6 실제 GPU 렌더링 성능은 미확인. 전체 명세 완료로 판정하지 않는다.','', '## 승인된 범위와 실행 게이트','', '- bottle·screw·carpet 3클래스를 모두 유지한다. bottle은 모델 차이가 작을 것으로 예상한 대조군이며 결과에 따라 제외하지 않는다.','- 본 실험 30조건 × 정책 A/B ×30seed ×3클래스 = 5,400회.','- 민감도 분석 inline0.5/profile: 시간10/60초, 민감도.98/.95, 특이도.98/.95를 한 번에 하나씩 변경. 6×3모델×30seed×3클래스 = 1,620회. 합계7,020회. 비용5/20/100은 후처리한다.',f"- 본 실행 전 별도30회: wall {gate['observed_pilot_wall_seconds']:.2f}초. 계층별 비용 외삽과25%여유 포함 예상 {gate['estimated_hours']:.3f}시간 ≤8시간으로 통과. 예상 저장량 {gate['estimated_storage_bytes']/1e9:.3f}GB. 실제 전체 시간은 완료 후 des_full/completion.json으로 구분한다.",'- 두 독립 CPU worker, spawn 사용. P1 GPU 실측과 P5 DES 계산 자원을 혼동하지 않는다. 승인된 목록 이외 탐색은 실행하지 않는다.','', '## P1 탐지·지연 실측','', '|클래스|선별기|실제 K|bank bytes|Pixel AP|test-oracle F1|FAISS p50/p95/p99 ms|NumPy p50 ms|','|---|---|---:|---:|---:|---:|---|---:|']
 for r in p1:lines.append(f"|{r['class_name']}|{r['selector']}|{r['K']}|{r['bank_bytes']}|{r['pixel_ap']:.6f}|{r['pixel_test_oracle_f1']:.6f}|{r['faiss_p50_ms']:.3f}/{r['faiss_p95_ms']:.3f}/{r['faiss_p99_ms']:.3f}|{r['numpy_p50_ms']:.3f}|")
 lines += ['', '- 공통 WR50 layer2+3/D1024/float32, L2정규화 cosine k1, density scoring off, sigma2. 기존 raw squared L2 연구 계열과 별도이다. CCIFPS 선택기 내부 설정은 별개로 보존했다.','- coreset은 정상 fit 전체 특징에 공식 ApproximateGreedy10%. random은 CCIFPS 실제 K와 동일. coreset과 CCIFPS의 K가 다르므로 전체방법 비교이며 동일-K 선별기 효과로 해석하지 않는다.','- screw의 실제 CCIFPS K=17,501을 그대로 기록했다. 명목17,500으로 치환하지 않았다.','- P1은 클래스당 고정 bank3개, 총9개. 측정은 각 bank/검색 backend마다50warmup+1,000회, 두backend 총18,000실측 호출. 모델18,000회 학습이 아니다.','- 정상 image holdout을 bank에서 제외하고 mean+3populationSD로 이미지 임계값을 고정했다. 표의 Pixel F1은 별도 test-oracle 값이며 공정 판정에 사용하지 않는다.',f"- exact FAISS IndexFlatIP vs NumPy: 9bank 전부 통과, 최대 점수차 {max(r['max_score_error'] for r in p1):.9g} ≤1e-5, 판정 변화 합 {sum(r['verdict_changes'] for r in p1)}. 같은 점수에서 nearest ID tie 차이는 별도 로그에 남겼다.",'- faiss/torch/CUDA/driver/GPU UUID/PID 및 cache hash는 p1_verified/<class>/environment.json, protocol.json, preflight.json에 있다. 원 aria 환경 package 목록은 전후 동일하며 별도 aria-faiss를 사용했다.','', '## 공정·GT 경계','', '- AI는 저장된 prediction/threshold를 재생하며 GT column을 입력으로 사용하지 않는다. GT 제거·변경에 대한 AI 불변성과 B의 GT 누락 실패를 tests/test_dt_replay.py로 검사했다.','- GT 라벨 판단은 reinspect_oracle과 평가기에 한정한다. 실행 provenance에서는 GT 파일 bytes의 SHA만 검사한다.','- 정책 A는 NG 즉시 폐기, B는 NG만 assumed 사람 재검사. 기본1.0/1.0,30초의 완벽 재검사는 실제 사람 성능 실측이 아니다. 재검사 이벤트 source=reinspect_oracle.','- 시간지연은 P1 실측 profile 또는 그 중앙값 고정. MTBF/MTTR·pitch·actuator 및 사람 정확도/시간은 assumed 태그.','- 공정 결과는3600초 중600초 warmup 제외. 30seed CI는 DES 난수 변동이며 고정 이미지 집합의 독립 일반화 평가가 아니다. MVTec test의 결함 비율을 현실 불량률로 주장하지 않는다.','', '## 회귀·CAD·화면','', '- backend132 passed (all-tests-after-dt.txt), frontend14 passed (frontend-tests.txt), constant6조건 기존 bytes 일치, vision golden diff0.','- 별도 PostgreSQL12.22/PostGIS3.0.0 fixture에서 실제 DB integration3개 통과. 원 환경과 시스템 서비스를 변경하지 않았다.','- conveyor/inspection_booth/diverter 각 STEP·FCStd·GLB·dims.json 생성. 설계 envelope bounding box 오차0mm. CAD 치수는 설계값이며 실제 센서 측정·충돌 검증이 아니다.',f"- 화면 검증: KPI/API 일치={br.get('kpi_match','미확인')}, 설정 동기화={br.get('config_match','미확인')}, 일시정지={br.get('pause_freezes','미확인')}. 원자료 browser_v2/report.json.",'- 하드웨어 GL 초기화 시도가 실패하고 SwiftShader로 fallback했다. 화면 기능 확인과 실제GPU FPS를 분리한다. 실제GPU 성능 통과로 기록하지 않는다.','', '## 발견한 실패와 처리','', '1. pytest 최초 탐색이 외부 FreeCAD 배포 테스트까지 수집해 실패: tests/만 명시해 프로젝트 검증. 최초 로그 보존.','2. FAISS GPU NumPy2 ABI 오류: 승인된 새 aria-faiss 환경 NumPy1.26.4 조합으로 해결. 원 환경 불변.','3. 기존 batch8 cache와 batch1 live 특징 차이: 같은batch8 설정으로 cache재현오차0을 확인. batch1지연 측정과 구분하며 허용오차를 늘리지 않았다.','4. metrics ndarray JSON 직렬화 오류: 직렬화 처리 수정 후 동일hash bank 재사용. 재선별하지 않았다.','5. 외부API 실행 후 화면선택값 불일치: 서버 snapshot 설정으로 동기화. 미완결seed의 CI는 표시하지 않도록 수정.','', '## 산출물과 현재 한계','', '- p1_summary.csv: 탐지·bank·지연·검색 일치 요약.','- des_pilot30/: 정확히30회 실측 및 cost_gate.json.','- des_full/: 원본 압축events·parts·모델·parameter tags·hash·run별 결과. 완료 후 verified_results.csv, summary_ci95.csv, paired_effects.csv, sensitivity_rank_changes.csv, REPORT.md.','- 초기 중단 보고서는 REPORT_initial_preflight.md에 보존한다. 최신 상태로 과거 로그를 덮어 설명하지 않는다.','- 추론시간의 CPU/GPU 공유 자원 영향, 인간 재검사 가정, 반복 이미지, blocking DES, 단순 CAD, 실제GPU 브라우저 미검증을 한계로 유지한다.','- Fusion Windows 제어 및 GitHub 게시 완료를 주장하지 않는다.']
 (OUT/'REPORT.md').write_text('\n'.join(lines)+'\n');(OUT/'gates.json').write_text(json.dumps(dict(p1_exact_search_passed=True,pilot30=gate,p5_verified=verify.exists(),p5_completed_markers=n,p6_hardware_gpu_verified=False,all_complete=False),indent=2));print(status)
if __name__=='__main__':main()
